import{_ as d,o as e,c as r,a5 as a}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"阅读证据卡：从读完摘要到真实交付","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/reading-evidence.zh.md","filePath":"public/downloads/worksheets/reading-evidence.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/reading-evidence.zh.md"};function i(l,t,b,n,o,s){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="阅读证据卡-从读完摘要到真实交付" tabindex="-1">阅读证据卡：从读完摘要到真实交付 <a class="header-anchor" href="#阅读证据卡-从读完摘要到真实交付" aria-label="Permalink to &quot;阅读证据卡：从读完摘要到真实交付&quot;">​</a></h1><p>“读完”只是一个动作，不是理解的证明。把这张卡复制到私有笔记中，每次记录一篇短文、一个章节、一个技术文档小节或一组来源。不要写入密码、客户资料、未获授权的第三方信息或不必要的隐私。</p><h2 id="_1-定义任务、读者与边界" tabindex="-1">1. 定义任务、读者与边界 <a class="header-anchor" href="#_1-定义任务、读者与边界" aria-label="Permalink to &quot;1. 定义任务、读者与边界&quot;">​</a></h2><h3 id="reading-evidence-yyyy-mm-dd" tabindex="-1">Reading Evidence - YYYY-MM-DD <a class="header-anchor" href="#reading-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Reading Evidence - YYYY-MM-DD&quot;">​</a></h3><p>真实场景：<br> 任务：定位信息 / 理解论证 / 读懂技术文档 / 建立耐力 / 综合来源 / 支持决定<br> 读完以后谁要知道、决定、执行或交接什么：<br> 完成标准：<br> 限时：<br> 允许的词典 / 翻译 / 搜索 / 笔记 / AI：<br> 版权、隐私与保存边界：</p><p>把完成标准写成结果，例如“能在当前版本运行最小示例”，不要只写“看完”。</p><h2 id="_2-记录来源与版本" tabindex="-1">2. 记录来源与版本 <a class="header-anchor" href="#_2-记录来源与版本" aria-label="Permalink to &quot;2. 记录来源与版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>主材料</th><th>平行材料</th><th>是否可比较</th></tr></thead><tbody><tr><td>作者/维护者、标题、链接</td><td></td><td></td><td></td></tr><tr><td>版本、发布日期或章节</td><td></td><td></td><td></td></tr><tr><td>访问日期与文本长度</td><td></td><td></td><td></td></tr><tr><td>作者/机构立场或利益关系</td><td></td><td></td><td></td></tr><tr><td>引用、图片、代码与版权边界</td><td></td><td></td><td></td></tr><tr><td>主题、体裁与难度</td><td></td><td></td><td></td></tr></tbody></table><p>网页会改版、付费或下架。保存必要的引用信息，不要未经许可复制整篇文章。</p><h2 id="_3-保存未经修饰的首读" tabindex="-1">3. 保存未经修饰的首读 <a class="header-anchor" href="#_3-保存未经修饰的首读" aria-label="Permalink to &quot;3. 保存未经修饰的首读&quot;">​</a></h2><p>首读条件：<br> 首读用时：<br> 是否逐词查词：<br> 一句话主旨：<br> 文章/文档怎样推进：<br> 三个确定细节：<br> 作者/维护者要我相信或完成什么：<br> 一个仍然不确定的地方：<br> 根据当前理解我会采取什么行动：</p><p>先完成首读，再查词或看解释。不要用翻译后更漂亮的摘要覆盖它。</p><h2 id="_4-建立六层障碍地图" tabindex="-1">4. 建立六层障碍地图 <a class="header-anchor" href="#_4-建立六层障碍地图" aria-label="Permalink to &quot;4. 建立六层障碍地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落/页码</th><th>我卡在哪里</th><th>障碍层</th><th>任务影响</th><th>本轮动作</th></tr></thead><tbody><tr><td></td><td></td><td>词汇与语法 / 结构与指向 / 背景与图式 / 论证与证据 / 版面与技术 / 注意力与容量</td><td>意思改变 / 任务阻断 / 高频重复 / 理解费力 / 低影响</td><td></td></tr></tbody></table><p>最影响任务的一到三个障碍：<br> 可以先略过的低影响词句：<br> 可能来自设备、版本、疲劳或环境的部分：</p><p>若几乎每句都阻断主旨，先换更容易的平行材料或补领域词块。降低入口不等于降低目标。</p><h2 id="_5-画主张、证据与限制" tabindex="-1">5. 画主张、证据与限制 <a class="header-anchor" href="#_5-画主张、证据与限制" aria-label="Permalink to &quot;5. 画主张、证据与限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落/页码</th><th>段落功能</th><th>作者主张</th><th>原文证据/例子</th><th>限制、反例或未知</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>原文直接说出的事实：<br> 有原文支持的推断：<br> 我自己的判断或联想：<br> 仍缺少的证据：<br> 什么新证据会改变我的判断：</p><p>把“作者说了什么”和“我是否同意”分开。技术、健康、法律或财务内容，回到可靠的一手来源或合格专业意见。</p><h2 id="_6-技术文档事实卡" tabindex="-1">6. 技术文档事实卡 <a class="header-anchor" href="#_6-技术文档事实卡" aria-label="Permalink to &quot;6. 技术文档事实卡&quot;">​</a></h2><p>如果材料是 API、SDK、迁移指南、命令行帮助、错误文档或 README，再补这一页：</p><p>目标与适用版本：<br> 前置条件、权限与环境：<br> 最小输入：<br> 预期输出：<br> 实际输出：<br> 默认值、范围、顺序或副作用：<br> 失败条件与错误信息：<br> 文档明确写出的限制：<br> 我仍然推测的部分：<br> 下一项最小测试：</p><p>读完技术文档却没有运行、手算、复现或确认一个最小事实，只能说明你看过页面，不能说明已经掌握。</p><h2 id="_7-生词、词族与翻译记录" tabindex="-1">7. 生词、词族与翻译记录 <a class="header-anchor" href="#_7-生词、词族与翻译记录" aria-label="Permalink to &quot;7. 生词、词族与翻译记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词/表达</th><th>在本任务中的作用</th><th>查到的定义/词族/搭配</th><th>原文位置</th><th>关闭工具后能否解释</th></tr></thead><tbody><tr><td></td><td>核心 / 反复 / 技术 / 低影响</td><td></td><td></td><td></td></tr></tbody></table><p>翻译帮助我补充的背景：<br> 翻译可能遮住的英文结构、语气或限定：<br> 我决定暂时不查的词：</p><p>未知词数量用于诊断材料难度，不直接决定水平。词族帮助猜测和覆盖率，但派生词不自动等于可用词。</p><h2 id="_8-多来源比较与真实输出" tabindex="-1">8. 多来源比较与真实输出 <a class="header-anchor" href="#_8-多来源比较与真实输出" aria-label="Permalink to &quot;8. 多来源比较与真实输出&quot;">​</a></h2><p>共同问题：<br> 来源 A 的定义、时间与证据：<br> 来源 B 的定义、时间与证据：<br> 各自省略或利益关系：<br> 哪些差异是事实，哪些是价值判断：</p><table tabindex="0"><thead><tr><th>输出</th><th>受众</th><th>我交付了什么</th><th>对方如何回应</th><th>依据是否可追溯</th></tr></thead><tbody><tr><td>确认邮件 / 最小测试 / 口头解释 / 决策备忘 / 交接</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>完成阅读之后，优先让读者、代码、决定或下一项任务检验你的理解。</p><h2 id="_9-记录工具与反馈" tabindex="-1">9. 记录工具与反馈 <a class="header-anchor" href="#_9-记录工具与反馈" aria-label="Permalink to &quot;9. 记录工具与反馈&quot;">​</a></h2><p>工具 / 反馈者 / 版本与日期：<br> 它看到了原文、我的首读还是我的摘要：<br> 它指出的遗漏位置：<br> 它是否混淆事实、推断和风格：<br> 教师/同伴/一手来源核验：<br> 我采纳 / 拒绝什么，为什么：</p><p>AI 可以提取候选术语、提问结构和生成平行任务，但可能编造摘要、引用、背景与作者意图。先保留自己的首读，再请求定位原文。</p><h2 id="_10-做延迟保持与迁移" tabindex="-1">10. 做延迟保持与迁移 <a class="header-anchor" href="#_10-做延迟保持与迁移" aria-label="Permalink to &quot;10. 做延迟保持与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>撤掉什么</th><th>改变的条件</th><th>输出</th><th>结果</th></tr></thead><tbody><tr><td>第 1 天</td><td>不用完整翻译或 AI 摘要</td><td>主材料</td><td>首读与五句重构</td><td></td></tr><tr><td>第 3-7 天</td><td>撤掉旧笔记与词典</td><td>平行材料</td><td>主旨、证据、推断</td><td></td></tr><tr><td>第 14 天</td><td>撤掉最近反馈</td><td>新主题或新体裁</td><td>解释、测试或决策备忘</td><td></td></tr><tr><td>第 30 天</td><td>关闭全部提示</td><td>真实文档、报告或交接</td><td>完整交付</td><td></td></tr></tbody></table><p>七天后仍能保留的方法：<br> 换材料后再次出现的障碍：<br> 是否更少逐词翻译或依赖摘要：<br> 哪一个读后动作仍然不稳定：<br> 下一轮只改变的变量：</p><h2 id="_11-评分与去留" tabindex="-1">11. 评分与去留 <a class="header-anchor" href="#_11-评分与去留" aria-label="Permalink to &quot;11. 评分与去留&quot;">​</a></h2><p>每项 0-2：<code>0=未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">第 1 天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>首读保留主线</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能区分主张、证据与推断</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能定位障碍层并选择动作</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能核验技术事实或来源位置</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>合上工具后能重构</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>换材料、主题或体裁后仍能交付</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>当前证据支持：继续主材料 / 降级为泛读 / 更换材料 / 转向另一问题<br> 最重要的依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/4-reading" target="_blank" rel="noreferrer">阅读篇：从逐词翻译到观点与证据</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/2-vocabulary" target="_blank" rel="noreferrer">词汇篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/grammar" target="_blank" rel="noreferrer">语法篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/3-listening" target="_blank" rel="noreferrer">听力篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/7-ai" target="_blank" rel="noreferrer">用 AI 学英语</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/reading-evidence" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',45)])])}const c=d(h,[["render",i]]);export{g as __pageData,c as default};
